 public MainWindow(){Title="AulaControl · Centro de supervisión";Width=1540;Height=900;MinWidth=1120;MinHeight=700;WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=Canvas;FontFamily=new FontFamily("Segoe UI");settings=Settings.Load();BuildUi();timer.Tick+=async(_,_)=>{RefreshStats();await RefreshWall();};timer.Start();Loaded+=(_,_)=>Configure();Closed+=(_,_)=>{discovery?.Dispose();timer.Stop();http.Dispose();};}
 Button B(string s,RoutedEventHandler h,SolidColorBrush? bg=null){var b=new Button{Content=s,Padding=new Thickness(14,9,14,9),Margin=new Thickness(4),Background=bg??Brushes.White,Foreground=bg==null?Ink:Brushes.White,BorderThickness=new Thickness(bg==null?1:0),BorderBrush=new SolidColorBrush(Color.FromRgb(216,225,220)),FontWeight=FontWeights.SemiBold,Cursor=System.Windows.Input.Cursors.Hand};b.Click+=h;return b;}Border Card(UIElement c,double pad=16)=>new(){Background=Brushes.White,CornerRadius=new CornerRadius(16),Padding=new Thickness(pad),BorderBrush=new SolidColorBrush(Color.FromRgb(226,233,229)),BorderThickness=new Thickness(1),Child=c};
 Border Stat(string title,string cap,TextBlock value,SolidColorBrush accent){value.FontSize=29;value.FontWeight=FontWeights.Bold;value.Foreground=Ink;value.Text="0";var s=new StackPanel();s.Children.Add(new TextBlock{Text=title,Foreground=accent,FontWeight=FontWeights.Bold,FontSize=11});s.Children.Add(value);s.Children.Add(new TextBlock{Text=cap,Foreground=Muted,FontSize=11});var c=Card(s,13);c.Margin=new Thickness(4);return c;}
 Image Logo(){var i=new Image{Width=68,Height=68,Stretch=Stretch.Uniform};try{i.Source=new BitmapImage(new Uri(LOGO));}catch{}return i;}
 void BuildUi(){var root=new Grid();root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(112)});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(100)});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(70)});root.RowDefinitions.Add(new RowDefinition());root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(38)});
  var head=new Border{Background=Dark,Padding=new Thickness(25,15,25,15)};var hg=new Grid();hg.ColumnDefinitions.Add(new ColumnDefinition());hg.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var left=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};left.Children.Add(new Border{Background=Brushes.White,CornerRadius=new CornerRadius(15),Padding=new Thickness(8),Child=Logo()});var tt=new StackPanel{Margin=new Thickness(16,0,0,0),VerticalAlignment=VerticalAlignment.Center};tt.Children.Add(new TextBlock{Text="AulaControl",Foreground=Brushes.White,FontSize=31,FontWeight=FontWeights.Bold});tt.Children.Add(new TextBlock{Text="Centro de supervisión · sesiones temporales · tráfico cifrado",Foreground=new SolidColorBrush(Color.FromRgb(204,231,218)),FontSize=14});left.Children.Add(tt);hg.Children.Add(left);var right=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};right.Children.Add(new Border{Background=new SolidColorBrush(Color.FromRgb(19,108,73)),CornerRadius=new CornerRadius(12),Padding=new Thickness(12,7,12,7),Margin=new Thickness(0,0,10,0),Child=new TextBlock{Text="AulaControl 1.3 Commercial",Foreground=Brushes.White,FontWeight=FontWeights.SemiBold}});right.Children.Add(B("⚙ Configuración",(_,_)=>ConfigDialog(),Orange));Grid.SetColumn(right,1);hg.Children.Add(right);head.Child=hg;root.Children.Add(head);root.Children.Add(new Border{Background=Orange,Height=4,VerticalAlignment=VerticalAlignment.Bottom});
  var stats=new Grid{Margin=new Thickness(20,7,20,3)};for(int i=0;i<5;i++)stats.ColumnDefinitions.Add(new ColumnDefinition());var a=Stat("EN LÍNEA","dispositivos visibles",statOnline,Green);stats.Children.Add(a);var b=Stat("EN VIVO","pantallas supervisadas",statLive,Green);Grid.SetColumn(b,1);stats.Children.Add(b);var c=Stat("ESTUDIANTES","sesiones activas",statStudents,Blue);Grid.SetColumn(c,2);stats.Children.Add(c);var d=Stat("PROFESORES","sesiones activas",statTeachers,Dark);Grid.SetColumn(d,3);stats.Children.Add(d);var e=Stat("ATENCIÓN","requieren revisión",statAlerts,Orange);Grid.SetColumn(e,4);stats.Children.Add(e);Grid.SetRow(stats,1);root.Children.Add(stats);
  var bar=new WrapPanel{Margin=new Thickness(20,5,20,5)};bar.Children.Add(B("✓ Seleccionar en línea",(_,_)=>SelectOnline()));bar.Children.Add(B("✉ Mensaje",async(_,_)=>await PromptSend("MESSAGE","Mensaje")));bar.Children.Add(B("↗ Enlace",async(_,_)=>await PromptSend("OPEN_URL","Abrir enlace")));bar.Children.Add(B("◉ Atención",async(_,_)=>await PromptSend("ATTENTION_ON","Mensaje de atención"),Dark));bar.Children.Add(B("✓ Liberar atención",async(_,_)=>await Send("ATTENTION_OFF"),Green));bar.Children.Add(B("⏏ Cerrar sesión",async(_,_)=>await Send("FORCE_LOGOUT"),Orange));bar.Children.Add(B("↻ Conexión",async(_,_)=>await Send("PING")));Grid.SetRow(bar,2);root.Children.Add(bar);
  var tabs=new TabControl{Margin=new Thickness(22,3,22,10),Background=Canvas,BorderThickness=new Thickness(0)};var live=new TabItem{Header="  Pantallas en vivo  ",Content=Card(new ScrollViewer{Content=wall,VerticalScrollBarVisibility=ScrollBarVisibility.Auto},4)};tabs.Items.Add(live);grid.ItemsSource=devices;AddCol("Estado","Status",105);AddCol("Dispositivo","Name",140);AddCol("Usuario","Person",185);AddCol("Rol","RoleText",100);AddCol("Curso","CourseText",105);AddCol("Supervisión","Supervision",130);AddCol("Gestión","Protection",125);AddCol("Batería","Battery",70,"{0}%");AddCol("Modelo","Model",170);AddCol("Android","Android",70);AddCol("IP","Ip",115);tabs.Items.Add(new TabItem{Header="  Dispositivos  ",Content=Card(grid,0)});Grid.SetRow(tabs,3);root.Children.Add(tabs);var foot=new Border{Background=new SolidColorBrush(Color.FromRgb(229,237,233)),Padding=new Thickness(18,9,18,9),Child=footer};Grid.SetRow(foot,4);root.Children.Add(foot);Content=root;}
 void AddCol(string h,string b,double w,string? fmt=null){var x=new DataGridTextColumn{Header=h,Binding=new Binding(b),Width=w};if(fmt!=null)((Binding)x.Binding).StringFormat=fmt;grid.Columns.Add(x);}
 void Configure(){if(string.IsNullOrWhiteSpace(settings.Key)){var k=Ask("Configuración inicial","Clave técnica del establecimiento",true);if(string.IsNullOrWhiteSpace(k)||k.Length<10){footer.Text="Configura una clave técnica para comenzar.";return;}settings.Key=k;settings.Save();}Start();}
 void Start(){discovery?.Dispose();devices.Clear();wall.Children.Clear();wallImages.Clear();wallStatus.Clear();wallSignature="";registry=new Registry(settings.Key);foreach(var x in registry.Load())devices.Add(x);commands=new Commands(settings.Key);discovery=new Discovery(settings.Key);discovery.Seen+=Incoming;try{discovery.Start();footer.Text="● Consola activa · identidad temporal, comandos y pantallas protegidos mediante autenticación y cifrado";}catch(Exception e){footer.Text="No se pudo abrir UDP 45888: "+e.Message;}RefreshStats();_=RefreshWall();}
 void Incoming(Device n)=>Dispatcher.Invoke(()=>{var d=devices.FirstOrDefault(x=>x.Id==n.Id);if(d==null){devices.Add(n);if(!string.IsNullOrWhiteSpace(n.User))SessionLog.Change(n.Id,"",n.User,n.Course);}else{string old=d.User;d.DeviceName=n.DeviceName;d.User=n.User;d.Course=n.Course;d.Role=n.Role;d.Model=n.Model;d.Android=n.Android;d.Ip=n.Ip;d.CommandPort=n.CommandPort;d.ScreenPort=n.ScreenPort;d.Battery=n.Battery;d.Screen=n.Screen;d.Managed=n.Managed;d.FrameAgeMs=n.FrameAgeMs;d.Seen=DateTime.Now;d.Identity();if(old!=d.User)SessionLog.Change(d.Id,old,d.User,d.Course);}registry?.Save(devices);RefreshStats();_=RefreshWall();});
 void RefreshStats(){foreach(var d in devices)d.Computed();var on=devices.Where(x=>x.IsOnline).ToList();statOnline.Text=on.Count.ToString();statLive.Text=on.Count(x=>!string.IsNullOrWhiteSpace(x.User)&&x.Screen).ToString();statStudents.Text=on.Count(x=>x.Role=="student").ToString();statTeachers.Text=on.Count(x=>x.Role=="teacher").ToString();statAlerts.Text=on.Count(x=>!string.IsNullOrWhiteSpace(x.User)&&!x.Screen).ToString();}
 string WallSignature()=>string.Join("|",devices.OrderBy(x=>x.Id).Select(x=>$"{x.Id}:{x.User}:{x.Role}:{x.Course}:{x.IsOnline}:{x.Screen}:{x.Managed}"));
 void RebuildWall(){wall.Children.Clear();wallImages.Clear();wallStatus.Clear();foreach(var d in devices.OrderByDescending(x=>x.IsOnline).ThenBy(x=>x.Name)){var g=new Grid();g.RowDefinitions.Add(new RowDefinition{Height=new GridLength(48)});g.RowDefinitions.Add(new RowDefinition());g.RowDefinitions.Add(new RowDefinition{Height=new GridLength(58)});var h=new Grid{Margin=new Thickness(12,8,12,6)};h.ColumnDefinitions.Add(new ColumnDefinition());h.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});h.Children.Add(new TextBlock{Text=d.Name,Foreground=Ink,FontSize=15,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center});var badge=new TextBlock{Text=d.Managed?"🔒":"⚠",Foreground=d.Managed?Green:Orange,FontSize=15,VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(badge,1);h.Children.Add(badge);g.Children.Add(h);var ib=new Border{Background=new SolidColorBrush(Color.FromRgb(10,18,15)),CornerRadius=new CornerRadius(10),Margin=new Thickness(8,0,8,0)};var im=new Image{Stretch=Stretch.Uniform};ib.Child=im;Grid.SetRow(ib,1);g.Children.Add(ib);wallImages[d.Id]=im;var st=new TextBlock{Foreground=Muted,FontWeight=FontWeights.SemiBold,Margin=new Thickness(12,7,12,7),TextWrapping=TextWrapping.Wrap};st.Text=WallText(d);Grid.SetRow(st,2);g.Children.Add(st);wallStatus[d.Id]=st;var card=Card(g,0);card.Width=326;card.Height=270;card.Margin=new Thickness(7);card.Cursor=System.Windows.Input.Cursors.Hand;card.MouseLeftButtonDown+=(_,_)=>{if(d.IsOnline&&d.Screen&&!string.IsNullOrWhiteSpace(d.User))new ViewerWindow(d,settings.Key){Owner=this}.Show();};wall.Children.Add(card);}if(devices.Count==0)wall.Children.Add(new TextBlock{Text="Esperando tablets AulaControl en la red…",Foreground=Muted,FontSize=18,Margin=new Thickness(25)});}
 string WallText(Device d)=>!d.IsOnline?"○ Sin conexión":string.IsNullOrWhiteSpace(d.User)?"○ Disponible · esperando identificación":d.Screen?$"● EN VIVO · {d.Person}\n{d.RoleText}{(string.IsNullOrWhiteSpace(d.Course)?"":" · "+d.Course)}":$"● {d.Person} · sesión sin pantalla";
 async Task RefreshWall(){if(wallBusy)return;wallBusy=true;try{var s=WallSignature();if(s!=wallSignature){wallSignature=s;RebuildWall();}await Task.WhenAll(devices.Where(d=>d.IsOnline).Select(FetchFrame));}finally{wallBusy=false;}}
 async Task FetchFrame(Device d){if(!wallStatus.TryGetValue(d.Id,out var st)||!wallImages.TryGetValue(d.Id,out var im))return;if(!d.IsOnline){st.Text="○ Sin conexión";im.Source=null;return;}if(string.IsNullOrWhiteSpace(d.User)){st.Text="○ Disponible · esperando identificación";st.Foreground=Blue;im.Source=null;return;}if(!d.Screen){st.Text=$"● {d.Person} · BLOQUEADA: sin supervisión";st.Foreground=Orange;im.Source=null;return;}try{long ts=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();using var q=new HttpRequestMessage(HttpMethod.Get,$"http://{d.Ip}:{d.ScreenPort}/screen.jpg");q.Headers.Add("X-Timestamp",ts.ToString());q.Headers.Add("X-Signature",AcCrypto.Hmac(settings.Key,$"SCREEN\n{ts}"));var r=await http.SendAsync(q);if(!r.IsSuccessStatusCode){st.Text=$"● {d.Person} · esperando cuadro…";st.Foreground=Orange;return;}byte[] z=AcCrypto.Open(settings.Key,await r.Content.ReadAsByteArrayAsync());using var ms=new MemoryStream(z);var bi=new BitmapImage();bi.BeginInit();bi.CacheOption=BitmapCacheOption.OnLoad;bi.DecodePixelWidth=305;bi.StreamSource=ms;bi.EndInit();bi.Freeze();im.Source=bi;st.Text=$"● EN VIVO · {d.Person}\n{d.RoleText}{(string.IsNullOrWhiteSpace(d.Course)?"":" · "+d.Course)}";st.Foreground=Green;}catch{st.Text=$"● {d.Person} · reconectando…";st.Foreground=Orange;}}
 List<Device> Sel()=>grid.SelectedItems.Cast<Device>().ToList();async Task Send(string a,string v=""){var s=Sel();if(s.Count==0){MessageBox.Show("Selecciona al menos una tablet en la pestaña Dispositivos.","AulaControl");return;}var rs=await Task.WhenAll(s.Where(x=>x.IsOnline).Select(async d=>(d,await commands!.Send(d,a,v))));foreach(var x in rs)if(!x.Item2.Item1)footer.Text=$"{x.d.Name}: {x.Item2.Item2}";}
 async Task PromptSend(string a,string title){var help=a=="MESSAGE"?"Escribe el mensaje que recibirá el usuario":a=="OPEN_URL"?"Escribe la URL completa":"Mensaje que ocupará la pantalla durante el modo Atención";var x=Ask(title,help,false);if(!string.IsNullOrWhiteSpace(x))await Send(a,x);}void SelectOnline(){grid.SelectedItems.Clear();foreach(var d in devices.Where(x=>x.IsOnline))grid.SelectedItems.Add(d);}void ConfigDialog(){var k=Ask("Configuración","Clave técnica del establecimiento",true,settings.Key);if(!string.IsNullOrWhiteSpace(k)&&k.Length>=10){settings.Key=k;settings.Save();Start();}}
 string? Ask(string title,string help,bool password,string initial=""){var w=new Window{Title=title,Width=540,Height=280,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=this,Background=Canvas};var p=new StackPanel{Margin=new Thickness(28)};p.Children.Add(new TextBlock{Text=title,FontSize=24,FontWeight=FontWeights.Bold,Foreground=Dark});p.Children.Add(new TextBlock{Text=help,Margin=new Thickness(0,7,0,14),TextWrapping=TextWrapping.Wrap,Foreground=Muted});Control input;if(password){var q=new PasswordBox{FontSize=17,Padding=new Thickness(12),Password=initial,Background=Brushes.White};input=q;}else{var q=new TextBox{FontSize=17,Padding=new Thickness(12),Text=initial,Background=Brushes.White};input=q;}p.Children.Add(input);var ok=B("Aceptar",(_,_)=>w.DialogResult=true,Green);ok.Margin=new Thickness(0,16,0,0);p.Children.Add(ok);w.Content=p;if(w.ShowDialog()!=true)return null;return password?((PasswordBox)input).Password:((TextBox)input).Text.Trim();}
